WITH cleaned AS (SELECT id, account_id, amount, txn_time, merchant, is_flagged, INITCAP(TRIM(txn_type)) AS txn_type_title, COALESCE(merchant, 'unassigned') AS merchant_filled, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE account_id = 5), with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id, merchant ORDER BY txn_time, id) AS seq_no, SUM(amount) OVER w_running AS running_amount, ROW_NUMBER() OVER (PARTITION BY merchant, account_id ORDER BY amount DESC, id) AS event_seq FROM cleaned WINDOW w_running AS (PARTITION BY merchant ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), prev_events AS (SELECT *, LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) AS prev_txn_time FROM with_windows), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), base AS (SELECT id, account_id, amount, txn_time, merchant, txn_type_title, resolved_merchant, seq_no, running_amount, prev_txn_time, is_new_burst, island_id, CASE WHEN is_flagged THEN 'Yes' ELSE 'No' END AS is_flagged_label, ROUND(island_id, 0) AS island_id_rounded FROM islands WHERE is_new_burst < 1), with_dims AS (SELECT e.*, d.opened_date, d.account_type, d.balance FROM base e LEFT JOIN accounts d ON e.account_id = d.id), with_dims_transactions AS (SELECT src.*, d.account_type AS account_account_type FROM with_dims src LEFT JOIN accounts d ON src.account_id = d.id) SELECT id, account_id, amount, txn_time, merchant, txn_type_title, seq_no, prev_txn_time, is_new_burst, CASE WHEN merchant RLIKE '^(Starbucks|Amazon)$' THEN 'GROUP_A' WHEN merchant RLIKE '^(Grab|7-Eleven)$' THEN 'CORE' ELSE 'EXTENDED' END AS merchant_zone FROM with_dims_transactions
